import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"坐标发生器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/coordinate_source/index.md","filePath":"v0.3.0-alpha/modules/coordinate_source/index.md"}'),r={name:"v0.3.0-alpha/modules/coordinate_source/index.md"};function n(i,t,c,h,s,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="坐标发生器" tabindex="-1">坐标发生器 <a class="header-anchor" href="#坐标发生器" aria-label="Permalink to &quot;坐标发生器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>coordinate_source</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>用初始位置和恒定速度生成局部平面的 <code>[x,y]</code> 坐标，可作为训练场定位实验的已知模型位置。x、y 的方向由实验约定；数值单位为米，不是经纬度，也不包含高度。</p><p>模型为 <code>p[n]=p0+v×n/Fs</code>。n 是从零开始累计的位置编号，Fs 是每秒产生的位置数量。第 0 个 item 就是初始位置；每个 item 含同一历元的 x、y 两个分量，不能把它们解释成两个先后样本。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>坐标发生器.position → 测距模拟器.position</code>，再接 <code>测距模拟器.ranges → 二维定位解算器.ranges</code>。捕获源位置时，显式选择分量 0 作为 x、1 作为 y，在 XY 中查看；两路须按同时间基准、同原始时刻精确配对。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>position</code>（二维位置）</td><td><code>numeric_f64</code></td><td>m；vlen=2</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>采样率描述每秒产生多少个完整位置 item，单位 Hz；位置单位为 m，速度单位为 m/s。初始位置描述起点，速度描述它之后怎样变化。若只想观察静止点，必须显式把两个速度都设为零。</p><p>增大采样率会缩短相邻位置点的时间间隔，不会改变以 m/s 表示的速度。在恒速模型中，10 Hz 对应间隔 0.1 s；它不是实际定位设备的更新率承诺。</p><p>参数范围和约束见下表。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>10</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>初始 x (m)<br><code>x0_m</code></td><td><code>3</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>重新准备</td></tr><tr><td>初始 y (m)<br><code>y0_m</code></td><td><code>4</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>重新准备</td></tr><tr><td>x 方向速度 (m/s)<br><code>vx_m_s</code></td><td><code>0.5</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>重新准备</td></tr><tr><td>y 方向速度 (m/s)<br><code>vy_m_s</code></td><td><code>0.25</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。停止后修改，再重新准备并运行；重准备从初始位置和新的运行时间基准开始，不能将新旧运行直接拼成连续运动轨迹。只改草稿或只准备，均不代表新参数已经产生数据。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="用三段距离解出平面坐标" tabindex="-1">用三段距离解出平面坐标 <a class="header-anchor" href="#用三段距离解出平面坐标" aria-label="Permalink to &quot;用三段距离解出平面坐标&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/01-position-from-ranges.cnsproj" download>下载 01-position-from-ranges.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 64 item；重新打开工程后需再次运行以取得数据。</p><p>用三段距离解出平面坐标</p><ul><li>静态位置 (3,4) m 的三距为 5、√65、√45 m；显式比较 x/y 分量，定位残差接近 0。</li></ul><p><a href="./../../learn/01-position-from-ranges/">三距定位课</a>从静止位置 <code>(3,4)</code> m 开始，再只改变初始 x。先看源位置，再看解算位置，避免将“已知模型输入”误当作真实测量结果。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>初始位置设为 <code>(3,4)</code>，为什么后来不在这里？</strong> 初始位置只描述第 0 个 item；非零速度会继续改变位置。静止对照要显式设两个速度为零。</p><p><strong>能直接把 x、y 送到地图吗？</strong> 不能据此当作地理坐标；本模型没有经纬度、地图原点转换或高度参考。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/01-position-from-ranges/">10 三段距离求位置</a></li></ul>',30)])])}const u=e(r,[["render",n]]);export{m as __pageData,u as default};
